// Lower bound: first index i with a[i] >= target (a.Length if none). Half-open [lo, hi).
static int LowerBound(int[] a, int target)
{
    int lo = 0, hi = a.Length;
    while (lo < hi) { var mid = lo + (hi - lo) / 2; if (a[mid] < target) lo = mid + 1; else hi = mid; }
    return lo;
}
