static bool HasCycle(Dictionary<string, List<string>> g)
{
    var state = new Dictionary<string, int>();               // 0 white, 1 grey, 2 black
    bool Dfs(string n)
    {
        state[n] = 1;
        foreach (var m in g.GetValueOrDefault(n, []))
